mapper.sql:
FROM cms_news n LEFT JOIN community_article a ON a.news_id = n.id WHERE n.is_deleted = 0
AND n.is_deleted = 0 AND n.publish_status = 1 AND n.publish_at<= CURRENT_TIMESTAMP AND (n.community_managed = 0 OR EXISTS( SELECT 1 FROM community_article pa LEFT JOIN user_account au ON au.id = pa.author_user_id AND au.is_deleted = 0 AND au.account_status = 1 WHERE pa.news_id = n.id AND pa.state = 'PUBLISHED' AND (au.id IS NOT NULL OR (pa.author_user_id IS NULL AND EXISTS( SELECT 1 FROM community_blogger eb WHERE eb.id = n.blogger_id AND eb.enabled = 1 AND eb.user_id IS NULL)))))
AND (NOT EXISTS( SELECT 1 FROM community_article_access ac WHERE ac.news_id = n.id AND ac.visibility<>'PUBLIC') OR ( SELECT va.author_user_id FROM community_article va WHERE va.news_id = n.id) = #{query.viewer} OR EXISTS( SELECT 1 FROM community_article_access ac JOIN community_article_reader ar ON ar.news_id = ac.news_id WHERE ac.news_id = n.id AND ac.visibility = 'FRIENDS' AND ar.user_id = #{query.viewer} AND EXISTS( SELECT 1 FROM community_follow f WHERE f.follower_id = #{query.viewer} AND f.target_key = CONCAT('u',( SELECT va.author_user_id FROM community_article va WHERE va.news_id = n.id)) AND f.following = 1) AND EXISTS( SELECT 1 FROM community_follow f WHERE f.follower_id = ( SELECT va.author_user_id FROM community_article va WHERE va.news_id = n.id) AND f.target_key = CONCAT('u',#{query.viewer}) AND f.following = 1))) AND NOT EXISTS( SELECT 1 FROM community_article_hidden ah WHERE ah.news_id = n.id AND ah.user_id = #{query.viewer})
AND EXISTS( SELECT 1 FROM community_article_tag atg JOIN community_tag t ON t.id = atg.tag_id WHERE atg.news_id = n.id AND t.enabled = 1
AND (t.code = 'other' OR LEFT(t.code,7) = 'custom_')
AND t.code = #{query.tag}
)
AND EXISTS( SELECT 1 FROM community_follow f WHERE f.follower_id = #{query.viewer} AND f.following = 1 AND (f.target_key = CONCAT('u',a.author_user_id) OR f.target_key = CONCAT('b',n.blogger_id) OR f.target_key = CONCAT('u',( SELECT b.user_id FROM community_blogger b WHERE b.id = n.blogger_id))))
AND (a.author_user_id = #{query.authorUser} OR EXISTS( SELECT 1 FROM community_blogger b WHERE b.id = n.blogger_id AND b.user_id = #{query.authorUser}))
AND n.blogger_id = #{query.blogger}
AND a.author_user_id = #{query.mine}
AND (CASE WHEN n.community_managed = 1 THEN COALESCE(a.state,'AI_PENDING') ELSE CASE n.publish_status WHEN 1 THEN 'PUBLISHED' WHEN 2 THEN 'HIDDEN' ELSE 'DRAFT' END END) = #{query.state}
AND n.community_managed =
1
0
AND (LOCATE(#{query.keyword},n.title)>0
OR EXISTS( SELECT 1 FROM user_profile p WHERE p.user_id = a.author_user_id AND p.is_deleted = 0 AND LOCATE(#{query.keyword},p.nickname)>0) OR EXISTS( SELECT 1 FROM community_blogger b WHERE b.id = n.blogger_id AND a.author_user_id IS NULL AND LOCATE(#{query.keyword},b.nickname)>0)
)

mapper.select:
SELECT enabled
FROM community_tag
WHERE code = #{code}

SELECT news_id
FROM community_article
WHERE author_user_id = #{author}
  AND client_request_id = #{clientRequestId}

SELECT COUNT(*)
FROM community_article
WHERE author_user_id = #{author}
  AND created_at>#{since}

mapper.update:
UPDATE community_article
SET state = 'AI_PENDING',revision = revision+1,ai_verdict = 'PENDING',ai_reason = '',ai_model = '',ai_checked_at = NULL,review_note = '',reviewed_by = NULL,reviewed_at = NULL,updated_at = CURRENT_TIMESTAMP
WHERE news_id = #{id}

mapper.select:
SELECT is_liked,is_collected
FROM news_user_action
WHERE news_id = #{id}
  AND user_id = #{viewer}
  AND is_deleted = 0

mapper.update:
UPDATE community_article
SET state = #{state},review_note = #{note},reviewed_by = #{admin},reviewed_at = CURRENT_TIMESTAMP,updated_at = CURRENT_TIMESTAMP
WHERE news_id = #{id}

UPDATE cms_news
SET publish_status = #{status},publish_at = CURRENT_TIMESTAMP,gmt_modified = CURRENT_TIMESTAMP
WHERE id = #{id}

UPDATE community_article
SET state = 'AI_PENDING',ai_verdict = 'PENDING',updated_at = CURRENT_TIMESTAMP
WHERE news_id = #{id}
